for file,title in [('face-front-000.png','Cận mặt lớn0° · trước / sau'),('face-three-quarter-045.png','Cận mặt lớn45° · trước / sau')]:page(title,'<p>PNG nguyên bản1200×1600 ở renders/before và renders/after. Cùng camera/ánh sáng; không retouch, không đổi góc để che lỗi.</p><div class="pair">'+img(r/'renders/before'/file,'P5.3A')+img(r/'renders/after'/file,'P5.3A-R')+'</div>')
